# Clean re-derive. Let me write a careful manual f, then test.
def solve(I):
    from collections import Counter
    cnt=Counter(x for row in I for x in row)
    bg=cnt.most_common(1)[0][0]
    best=None
    for v,_ in cnt.items():
        if v==bg: continue
        pts=[(r,c) for r in range(len(I)) for c in range(len(I[0])) if I[r][c]==v]
        rs=[p[0] for p in pts]; cl=[p[1] for p in pts]
        h=max(rs)-min(rs)+1; w=max(cl)-min(cl)+1
        if len(pts)==2*h+2*w-4 and h>=4 and w>=4:
            best=(v,min(rs),min(cl),h,w); break
    vf,fr,fcl,h,w=best
    cs=[(r,c,I[r][c]) for r in range(len(I)) for c in range(len(I[0])) if I[r][c] not in (bg,vf) and not (fr<=r<=fr+h-1 and fcl<=c<=fcl+w-1)]
    rr=[p[0] for p in cs]; cc=[p[1] for p in cs]
    ch=max(rr)-min(rr)+1 or 1; cw=max(cc)-min(cc)+1 or 1
    ih,iw=h-2,w-2
    out=[[None]*w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if r in (0,h-1) or c in (0,w-1): out[r][c]=vf
    for r2,c2,v in cs:
        kr=int(round((r2-min(rr))*ih/ch)); kc=int(round((c2-min(cc))*iw/cw))
        br=(ih)//max(ch,1); bc=(iw)//max(cw,1)
        # fill block rows 1+kr? demo: band size = ih/3 =5 ; blocks at rows 1..5 etc. Block index k -> rows 1+k*br ... 1+(k+1)*br-1
        for R in range(1+kr*br, 1+(kr+1)*br):
            for C in range(1+kc*bc, 1+(kc+1)*bc):
                out[R][C]=v
    for r in range(h):
        for c in range(w):
            if out[r][c] is None: out[r][c]=bg
    return out
